-- say_phrase («Сказать фразу»), правила v5: добавлен режим ответа ученика voiceReply — «голосовое с текстом».
-- voiceReply: true — реплика ученика в чате приходит и текстом, и голосовым сообщением (звук только в памяти телефона на время урока);
-- нет поля = только текст; голосовое доступно, лишь когда речь распознаёт Vosk (иначе придёт текст).
-- Предыдущие миграции (…110000, …120000, …130000, 20261010120000) уже могли быть применены, поэтому текст правила ОБНОВЛЯЕМ, а не правим старые файлы.
-- Таблиц, колонок, политик и функций не меняем. Идемпотентно: повторный запуск пишет тот же текст; если правила ещё нет — вставляем.
-- Текст тот же, что в lessonRulesDefaults.js (следит sayPhraseLessonIo.test.js).
do $migration$
declare
  t text := $rule$say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ английскую фразу в микрофон, приложение мягко сверяет её с эталоном (порядок слов не важен, мелкие неточности прощаются, звук не записывается и не сохраняется). phrase — эталон: обычная разговорная фраза на 3–8 слов с целевым словом урока, без перевода внутри; он нужен для проверки и озвучки, а САМ МОДУЛЬ НИЧЕГО В ЧАТ НЕ ПИШЕТ и фразу в панели не показывает (в панели только «Произнесите фразу»), поэтому задание формулирует ПРЕДЫДУЩЕЕ сообщение — короткая текстовая нода прямо перед say_phrase: напиши в ней саму фразу и что сказать вслух. translation — справочно (ученику не показывается); keywords — 1–2 ключевых слова из phrase через запятую (они должны прозвучать обязательно); threshold — 70 по умолчанию (50–100); strict: true — «Строго» (100% слов, точно, без опечаток и без слов, которые распознаватель «домыслил»; у новых нод в редакторе включено, в JSON отсутствие поля = false); voiceReply: true — реплика ученика в чате приходит не только текстом, но и голосовым сообщением (его можно прослушать; звук живёт только в памяти телефона на время урока и нигде не сохраняется), нет поля = только текст; голосовое доступно, лишь когда речь распознаёт Vosk, иначе (Firefox, системное распознавание) придёт только текст. Схема «пара сообщений вокруг say_phrase»: [текстовая нода-задание] → [say_phrase] → [текстовая нода-успех: коротко сообщает, что получилось]. Кнопок «Ещё раз» и «Получилось» нет: после неудачи ученик снова жмёт на микрофон, а подсказка приходит в ЧАТ пузырём слева от ведущего (внутри самой панели текстов-подсказок нет): hintsOn: false отключает все подсказки (нет поля = включены), hintSilence — «не слышу вас», hintMismatch — «сказано не то», hintPartial — «почти получилось», в нём работают автоподстановки {ok} (верно произнесённые слова фразы) и {missed} (не произнесённые или неверные); пустое поле = стандартный текст, свои тексты нужны только если хочешь другой тон. Попытки: ученик пробует, пока не набралось три неудачные (попытка считается, когда что-то распознано, пусть и неверно; тишина попытку не тратит, три тишины подряд — одна неудача). После третьей неудачи урок идёт по выходу say_wrong («неверный»), при успехе — по say_done («верный»). Кнопка «Я не могу говорить» (её можно нажать на любой попытке) ВСЕГДА ведёт по say_done, но сообщение-успех сразу после модуля при этом пропускается (хвалить не за что); пропуск разовый и касается только этого модуля. Поэтому: перед модулем ставь одну короткую текстовую ноду с заданием, после say_done — одну короткую ноду «Получилось!» (пропускается только обычная текстовая нода с единственным входом от say_phrase и единственным выходом дальше; иначе она покажется как обычно). На say_wrong повесь своё продолжение (например, короткий разбор или подсказку): оно покажется после третьей неудачи; ветка необязательна — если соединён только один выход, урок идёт по нему. Не ставь say_phrase первой нодой урока и две подряд. Триггеры: say_done («верный») и say_wrong («неверный»; в старых уроках встречается прежнее имя say_skip — оно читается как say_wrong).$rule$;
begin
  update public.lesson_rules
  set rule_text = t
  where rule_text like 'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ%';
  if not found then
    insert into public.lesson_rules (rule_text, sort_order, category) values (t, 250, 'principle');
  end if;
end
$migration$;
